export async function createPaddleOCR(signal,onProgress){const worker=new Worker(new URL('./paddle-ocr-worker.js?v=20261027review',import.meta.url),{type:'module'});let sequence=0;const pending=new Map();const terminate=()=>{worker.terminate();for(const p of pending.values())p.reject(Error('文字识别已停止'));pending.clear();signal.removeEventListener('abort',terminate);return Promise.resolve()};signal.addEventListener('abort',terminate,{once:true});worker.onmessage=({data})=>{if(data.type==='progress'){if(!signal.aborted)onProgress(data.text);return}const p=pending.get(data.id);if(!p)return;pending.delete(data.id);if(data.type==='error')p.reject(Error(data.text));else p.resolve(data.result)};worker.onerror=()=>{for(const p of pending.values())p.reject(Error('PaddleOCR 浏览器引擎加载失败；不会转用收费服务'));terminate()};const call=(type,data={},transfer=[])=>new Promise((resolve,reject)=>{if(signal.aborted)return reject(Error('文字识别已停止'));const id=++sequence;pending.set(id,{resolve,reject});worker.postMessage({type,id,...data},transfer)});try{await call('load');return{terminate,async recognize(canvas){const pixels=canvas.getContext('2d',{willReadFrequently:true}).getImageData(0,0,canvas.width,canvas.height).data.slice();return call('recognize',{pixels:pixels.buffer,width:canvas.width,height:canvas.height},[pixels.buffer])}}}catch(e){await terminate();throw e}}
